// Writes packages/contracts/src/index.ts re-exporting every generated type.
import { readdirSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dir = join(root, "packages/contracts/src/generated");
const names = readdirSync(dir)
  .filter((f) => f.endsWith(".ts"))
  .map((f) => f.replace(/\.ts$/, ""))
  .sort();
const body =
  "// Generated by scripts/gen-contracts-index.mjs from ts-rs output. Do not edit.\n" +
  names.map((n) => `export type { ${n} } from "./generated/${n}";`).join("\n") +
  "\n";
writeFileSync(join(root, "packages/contracts/src/index.ts"), body);
console.log(`contracts: ${names.length} types`);
